describe('Browser Push Notifications for Urgent Alerts', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display browser push notification when urgent alert is received', () => {
    // Intercept the API call that triggers the push notification
    cy.intercept('POST', '/api/alerts/urgent').as('urgentAlert');

    // Click the button to trigger an urgent alert
    cy.get('[data-testid="trigger-urgent-alert-btn"]').click();

    // Wait for the API call to complete
    cy.wait('@urgentAlert');

    // Verify the notification appears in the UI
    cy.get('[data-testid="notification-banner"]').should('be.visible');
    cy.get('[data-testid="notification-banner"]').should('contain', 'Urgent Alert');

    // Verify the notification has the correct styling for urgency
    cy.get('[data-testid="notification-banner"]').should('have.class', 'notification-urgent');

    // Verify the notification has a close button
    cy.get('[data-testid="notification-close-btn"]').should('be.visible');

    // Verify the notification content is correct
    cy.get('[data-testid="notification-message"]').should('contain', 'System maintenance scheduled');
  });

  it('should handle browser permission denial for push notifications', () => {
    // Mock the browser permission API to simulate denial
    cy.window().then((win) => {
      cy.stub(win.Notification, 'requestPermission').resolves('denied');
    });

    // Attempt to trigger an urgent alert
    cy.get('[data-testid="trigger-urgent-alert-btn"]').click();

    // Verify the notification banner does not appear
    cy.get('[data-testid="notification-banner"]').should('not.exist');

    // Verify a fallback message is displayed instead
    cy.get('[data-testid="permission-denied-message"]').should('be.visible');
    cy.get('[data-testid="permission-denied-message"]').should('contain', 'Push notifications are disabled');

    // Verify the user is prompted to enable notifications
    cy.get('[data-testid="enable-notifications-btn"]').should('be.visible');
    cy.get('[data-testid="enable-notifications-btn"]').should('contain', 'Enable Notifications');

    // Verify the user can still interact with the dashboard
    cy.get('[data-testid="dashboard-content"]').should('be.visible');
  });
});
